#include <stdio.h>
#include <stdlib.h>
int main(void)
{
    int *values = malloc(3 * sizeof *values);
    if (values == NULL) return 1;
    for (size_t i = 0; i < 3; ++i) { values[i] = (int)(i * 10); printf("%d\n", values[i]); }
    free(values); return 0;
}

#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>
bool index_is_valid(size_t index, size_t length) { return index < length; }
int main(void)
{
    if (!index_is_valid(0, 3) || !index_is_valid(2, 3) || index_is_valid(3, 3) || index_is_valid(0, 0)) {
        fputs("boundary test failed\n", stderr); return 1;
    }
    puts("boundary tests passed"); return 0;
}
